#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t len;
    const unsigned char *key;
    const unsigned char *nonce;
    uint32_t counter;
} chacha_job;

static void* chacha_worker(void *arg) {
    chacha_job *j = (chacha_job*)arg;
    unsigned char iv[16];
    memset(iv, 0, 4);
    memcpy(iv + 4, j->nonce, 12);
    uint32_t ctr = j->counter;
    iv[0] = ctr & 0xff; iv[1] = (ctr>>8)&0xff; iv[2]=(ctr>>16)&0xff; iv[3]=(ctr>>24)&0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, iv);
    int outl = 0;
    EVP_EncryptUpdate(ctx, j->ct, &outl, j->pt, (int)j->len);
    EVP_EncryptFinal_ex(ctx, j->ct + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

// poly1305 key = first 32 bytes of chacha20 keystream (counter 0)
static void poly1305_keygen(const unsigned char *key, const unsigned char *nonce, unsigned char *out) {
    unsigned char iv[16];
    memset(iv, 0, 16);
    memcpy(iv + 4, nonce, 12);
    unsigned char zero[32];
    memset(zero, 0, 32);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    int outl = 0;
    EVP_EncryptUpdate(ctx, out, &outl, zero, 32);
    EVP_EncryptFinal_ex(ctx, out + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
}

// solve: returns 0 on success. out_ct must be len(plaintext), out_tag 16 bytes.
int solve_chacha(const unsigned char *key, const unsigned char *nonce,
                 const unsigned char *pt, size_t ptlen,
                 const unsigned char *aad, size_t aadlen,
                 unsigned char *out_ct, unsigned char *out_tag) {
    int nthreads = 4;
    // chacha20 encrypt in parallel
    if (ptlen > 0) {
        size_t chunk = (ptlen / nthreads) & ~(size_t)63; // multiple of 64
        if (chunk == 0) chunk = 64;
        pthread_t th[16];
        chacha_job jobs[16];
        int nt = 0;
        size_t off = 0;
        while (off < ptlen) {
            size_t len = ptlen - off;
            if (len > chunk) len = chunk;
            jobs[nt].pt = pt + off;
            jobs[nt].ct = out_ct + off;
            jobs[nt].len = len;
            jobs[nt].key = key;
            jobs[nt].nonce = nonce;
            jobs[nt].counter = (uint32_t)(off / 64) + 1;
            pthread_create(&th[nt], NULL, chacha_worker, &jobs[nt]);
            nt++;
            off += len;
        }
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
    }
    // poly1305
    unsigned char pkey[32];
    poly1305_keygen(key, nonce, pkey);
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
    EVP_MAC_init(mctx, pkey, 32, NULL);
    // aad
    if (aadlen > 0) EVP_MAC_update(mctx, aad, aadlen);
    // pad aad to 16
    size_t pad = (16 - (aadlen % 16)) % 16;
    static const unsigned char zeros[16] = {0};
    if (pad) EVP_MAC_update(mctx, zeros, pad);
    // ciphertext
    if (ptlen > 0) EVP_MAC_update(mctx, out_ct, ptlen);
    pad = (16 - (ptlen % 16)) % 16;
    if (pad) EVP_MAC_update(mctx, zeros, pad);
    // lengths (little endian 64-bit)
    unsigned char lens[16];
    uint64_t al = aadlen, cl = ptlen;
    for (int i = 0; i < 8; i++) { lens[i] = (al >> (8*i)) & 0xff; lens[8+i] = (cl >> (8*i)) & 0xff; }
    EVP_MAC_update(mctx, lens, 16);
    size_t outl = 16;
    EVP_MAC_final(mctx, out_tag, &outl, 16);
    EVP_MAC_CTX_free(mctx);
    EVP_MAC_free(mac);
    return 0;
}
